// The hidden select preserves the existing saved values; only the input presentation changes.
function setConfidence(value=$('confidence').value,disabled=$('confidence').disabled){const input=$('confidence');input.value=value||'';input.disabled=disabled;document.querySelectorAll('#confidence-buttons button').forEach(button=>{const checked=button.dataset.confidence===input.value;button.setAttribute('aria-checked',String(checked));button.disabled=disabled;button.tabIndex=checked&&!disabled?0:-1})}
function chooseConfidence(button){if(button.disabled)return;setConfidence(button.dataset.confidence);if(examRun&&!examRun.finished)captureExamDraft();else saveExerciseDraft()}
