$('confidence-buttons').addEventListener('keydown',e=>{const buttons=[...document.querySelectorAll('#confidence-buttons button')],index=buttons.indexOf(document.activeElement);if(index<0||buttons[index].disabled)return;let next;if(['ArrowRight','ArrowDown'].includes(e.key))next=(index+1)%buttons.length;else if(['ArrowLeft','ArrowUp'].includes(e.key))next=(index+buttons.length-1)%buttons.length;else if(e.key==='Home')next=0;else if(e.key==='End')next=buttons.length-1;else return;e.preventDefault();chooseConfidence(buttons[next]);buttons[next].focus()});
let helpReturn=null;
$('open-help').onclick=()=>{helpReturn={focus:document.activeElement,x:scrollX,y:scrollY};tickExam();const frame=$('help-frame');if(!frame.src)frame.src=frame.dataset.src;$('help-dialog').showModal();frame.focus()};
