function flagChecks(qid,selected){return ExamStorage.flagIds.map(id=>`<label><input type="checkbox" value="${id}" ${selected.includes(id)?'checked':''}>${esc(ExamStorage.flags()[id])}</label>`).join('')}
function renderQuestionFlags(qid,container='question-flags'){const el=$(container),status=$(container==='review-flags'?'review-flag-save-status':'flag-save-status');el.innerHTML=flagChecks(qid,ExamStorage.questionFlags(qid));el.onchange=()=>{try{ExamStorage.setQuestionFlags(qid,[...el.querySelectorAll('input:checked')].map(x=>x.value));status.textContent='フラグを保存しました。'}catch(e){el.innerHTML=flagChecks(qid,ExamStorage.questionFlags(qid));status.textContent='フラグを保存できませんでした：'+e.message}}}
function flagBadges(qid){const names=ExamStorage.flags();return '<div class="flag-badges">'+ExamStorage.questionFlags(qid).map(id=>`<span class="badge">${esc(names[id])}</span>`).join('')+'</div>'}

function openEditor(id){saveExerciseDraft();editorOrigin={view:state.view,x:scrollX,y:scrollY,selected:[...document.querySelectorAll('input[name=choice]:checked')].map(x=>x.value),confidence:$('confidence').value};ExamEditor.open(id);}
let renderToken=0;let displayedAssets={};
const imageViewer={scale:1,x:0,y:0,trigger:null,drag:null,suppressClick:false};
function applyImageTransform(){const image=$('image-viewer-image');image.style.transform=`translate(${imageViewer.x}px,${imageViewer.y}px) scale(${imageViewer.scale})`}
function resetImageView(){imageViewer.scale=1;imageViewer.x=0;imageViewer.y=0;applyImageTransform()}
function zoomImage(next,clientX=null,clientY=null){const stage=$('image-viewer-stage'),old=imageViewer.scale,value=Math.min(5,Math.max(.5,next));if(value===old)return;const rect=stage.getBoundingClientRect(),px=clientX==null?0:clientX-(rect.left+rect.width/2),py=clientY==null?0:clientY-(rect.top+rect.height/2),ratio=value/old;imageViewer.x=px-(px-imageViewer.x)*ratio;imageViewer.y=py-(py-imageViewer.y)*ratio;imageViewer.scale=value;applyImageTransform()}
function restoreImageFocus(){document.body.classList.remove('image-viewer-open');const trigger=imageViewer.trigger;imageViewer.trigger=null;trigger?.isConnected&&trigger.focus()}
function openImageViewer(img){const dialog=$('image-viewer');imageViewer.trigger=img;$('image-viewer-title').textContent=img.alt||'問題画像';$('image-viewer-image').src=img.src;$('image-viewer-image').alt=img.alt||'問題画像';resetImageView();document.body.classList.add('image-viewer-open');if(typeof dialog.showModal==='function')dialog.showModal();else{dialog.setAttribute('open','');dialog.classList.add('is-fallback');dialog.setAttribute('aria-modal','true')}requestAnimationFrame(()=>$('image-viewer-stage').focus())}
function closeImageViewer(){const dialog=$('image-viewer');if(!dialog.hasAttribute('open'))return;if(typeof dialog.close==='function'&&!dialog.classList.contains('is-fallback'))dialog.close();else{dialog.removeAttribute('open');dialog.classList.remove('is-fallback');dialog.removeAttribute('aria-modal');restoreImageFocus()}}
function initImageViewer(){const dialog=$('image-viewer'),stage=$('image-viewer-stage'),image=$('image-viewer-image');$('image-zoom-in').onclick=()=>zoomImage(imageViewer.scale*1.25);$('image-zoom-out').onclick=()=>zoomImage(imageViewer.scale/1.25);$('image-zoom-reset').onclick=resetImageView;$('image-viewer-close').onclick=closeImageViewer;dialog.addEventListener('click',e=>{if(e.target===dialog)closeImageViewer()});dialog.addEventListener('close',restoreImageFocus);image.addEventListener('click',e=>{imageViewer.suppressClick=false;e.stopPropagation()});stage.addEventListener('wheel',e=>{e.preventDefault();zoomImage(imageViewer.scale*(e.deltaY<0?1.12:.89),e.clientX,e.clientY)},{passive:false});stage.addEventListener('pointerdown',e=>{if(e.button!==0||imageViewer.scale<=1)return;imageViewer.drag={id:e.pointerId,x:e.clientX,y:e.clientY,originX:imageViewer.x,originY:imageViewer.y};imageViewer.suppressClick=false;stage.setPointerCapture(e.pointerId);stage.classList.add('is-dragging')});stage.addEventListener('pointermove',e=>{const drag=imageViewer.drag;if(!drag||drag.id!==e.pointerId)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.abs(dx)+Math.abs(dy)>4)imageViewer.suppressClick=true;imageViewer.x=drag.originX+dx;imageViewer.y=drag.originY+dy;applyImageTransform()});const endDrag=e=>{if(imageViewer.drag?.id!==e.pointerId)return;imageViewer.drag=null;stage.classList.remove('is-dragging')};stage.addEventListener('pointerup',endDrag);stage.addEventListener('pointercancel',endDrag);stage.addEventListener('click',e=>{if(imageViewer.suppressClick){imageViewer.suppressClick=false;return}if(e.target===stage)closeImageViewer()});stage.addEventListener('keydown',e=>{if(e.key==='+'||e.key==='='){e.preventDefault();zoomImage(imageViewer.scale*1.25)}else if(e.key==='-'||e.key==='_'){e.preventDefault();zoomImage(imageViewer.scale/1.25)}else if(e.key==='0'){e.preventDefault();resetImageView()}});document.addEventListener('keydown',e=>{if(!dialog.hasAttribute('open'))return;if(e.key==='Escape'){e.preventDefault();closeImageViewer();return}if(e.key!=='Tab'||!dialog.classList.contains('is-fallback'))return;const focusable=[...dialog.querySelectorAll('button:not([disabled])'),stage],first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}else if(!focusable.includes(document.activeElement)){e.preventDefault();first.focus()}});window.addEventListener('resize',()=>{if(dialog.hasAttribute('open'))resetImageView()})}
const navStackKey='exam-study-minimal.navigation.v3';
const searchSessionKey=id=>`exam-study-minimal.search-session.v1.${id}`;
function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function uuid(){return crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random()}`}
function qs(o){const p=new URLSearchParams();Object.entries(o).forEach(([k,v])=>{if(Array.isArray(v)){v.forEach(x=>p.append(k,x))}else if(v!==''&&v!=null&&v!==false)p.set(k,v)});return p.toString()}
function persistSearchSession(){if(state.searchSession?.sessionId)sessionStorage.setItem(searchSessionKey(state.searchSession.sessionId),JSON.stringify(state.searchSession))}
function latestSearchSession(saved){if(!saved?.sessionId)return saved||null;try{const latest=JSON.parse(sessionStorage.getItem(searchSessionKey(saved.sessionId)));return ExamModel.mergeSearchSession(saved,latest)}catch{return saved}}
function snapshot(){persistSearchSession();return {scope:state.scope,filters:structuredClone(state.filters),sort:state.filters.sort,page:state.page,page_size:state.pageSize,scroll_anchor:getAnchor(),entry_id:uuid(),parent_entry_id:history.state?.entry_id||null,currentId:state.currentId,originId:state.originId,view:state.view,studyView:state.studyView,lastAttemptId:state.lastAttemptId,searchSession:state.searchSession?{sessionId:state.searchSession.sessionId}:null,relationTrail:structuredClone(state.relationTrail),scrollY:scrollY}}
function getAnchor(){if(state.view!=='list')return null;const el=document.querySelector('.qrow[data-id]');return el?.dataset.id||null}
function pushNav(){const s=snapshot();history.pushState(s,'',location.pathname+'#'+routeHash());sessionStorage.setItem(navStackKey,JSON.stringify(s))}
function replaceNav(){const old=history.state||{};const s={...snapshot(),entry_id:old.entry_id||uuid(),parent_entry_id:old.parent_entry_id||null};history.replaceState(s,'',location.pathname+'#'+routeHash());sessionStorage.setItem(navStackKey,JSON.stringify(s))}
function routeHash(){if(state.view==='exercise')return `question=${encodeURIComponent(state.currentId)}`;const x={scope:state.scope,origin:state.originId||'',q:state.filters.keyword,term:state.filters.term,session:state.filters.session,type:state.filters.examType,half:state.filters.examHalf,booklet:state.filters.booklet,category:state.filters.category,learning:state.filters.learning,...Object.fromEntries(reviewFields.map(([k])=>[k,state.filters[k]])),excludeOvercome:state.filters.excludeOvercome,overcomeCount:state.filters.overcomeCount,flags:state.filters.flags,sort:state.filters.sort,page:state.page,page_size:state.pageSize};state.filters.departments.forEach(d=>x['dept']=(x['dept']?x['dept']+',':'')+d);state.filters.diseases.forEach(d=>x['disease']=(x['disease']?x['disease']+',':'')+d);return qs(x)}
function restore(s){if(!s)return false;Object.assign(state,{scope:s.scope||'all',filters:{...state.filters,...(s.filters||{})},page:s.page||1,pageSize:s.page_size||10,currentId:s.currentId||null,originId:s.originId||null,view:s.view||'list',studyView:!!s.studyView,lastAttemptId:s.lastAttemptId||null,searchSession:latestSearchSession(s.searchSession),relationTrail:Array.isArray(s.relationTrail)?s.relationTrail:[]});render();setTimeout(()=>{if(s.scroll_anchor){document.querySelector(`[data-id="${CSS.escape(s.scroll_anchor)}"]`)?.scrollIntoView()}else scrollTo(0,s.scrollY||0)},0);return true}
window.addEventListener('popstate',e=>{if(examRun&&!examRun.finished){captureExamDraft();resumeExam();return}if(!restore(e.state)){state.view='list';state.scope='all';state.currentId=null;render()}});

const raw=await ExamEditor.load();state.data=ExamAdapter.adapt(raw);state.questions=state.data.questions;ExamEditor.init(raw,(updated)=>{
 state.data=ExamAdapter.adapt(updated);state.questions=state.data.questions;
 const origin=editorOrigin;render();
 if(origin?.view==='exercise'&&!state.studyView&&!state.lastAttemptId){document.querySelectorAll('input[name=choice]').forEach(x=>x.checked=origin.selected.includes(x.value));setConfidence(origin.confidence);}
 replaceNav();requestAnimationFrame(()=>scrollTo(origin?.x||0,origin?.y||0));editorOrigin=null;
});PackageManager.init();initImageViewer();
const selections=v=>Array.isArray(v)?v.map(String):v==null||v===''?[]:[String(v)];
for(const [id,key,fixed] of [['f-term','term',[]],['f-session','session',['I','II','III']],['f-type','examType',['本試','追試']],['f-half','examHalf',['前半','後半']],['f-booklet','booklet',['A','B','C','D','E','F']]]){
 const values=[...new Set([...fixed,...state.questions.map(q=>q[key]).filter(v=>v!=null).map(String)])].sort((a,b)=>fixed.length?fixed.indexOf(a)-fixed.indexOf(b):b.localeCompare(a,'ja',{numeric:true}));
 $(id).innerHTML=values.map(val=>`<label class="inline-check"><input type="checkbox" value="${esc(val)}">${esc(id==='f-term'?val+'期':id==='f-type'&&val==='追試'?'再試（追試）':val)}</label>`).join('');
}
for(const id of ['filter-details','department-details','disease-details']){const el=$(id),key='exam-study.ui.disclosure.'+id;const saved=sessionStorage.getItem(key);if(saved!==null)el.open=saved==='open';el.addEventListener('toggle',()=>sessionStorage.setItem(key,el.open?'open':'closed'));}


function readFilters(){for(const [key,id] of reviewFields){const input=$(id);if(input.value!==''&&!input.checkValidity())return;state.filters[key]=input.value}if(!$('f-overcome-count').checkValidity())return;state.filters.overcomeCount=$('f-overcome-count').value||'3';state.filters.excludeOvercome=$('f-exclude-overcome').checked;state.filters.flags=[...document.querySelectorAll('#f-flags input:checked')].map(x=>x.value);state.filters.keyword=$('f-keyword').value.trim();state.filters.term=[...document.querySelectorAll('#f-term input:checked')].map(x=>x.value);state.filters.session=[...document.querySelectorAll('#f-session input:checked')].map(x=>x.value);state.filters.examType=[...document.querySelectorAll('#f-type input:checked')].map(x=>x.value);state.filters.examHalf=[...document.querySelectorAll('#f-half input:checked')].map(x=>x.value);state.filters.booklet=[...document.querySelectorAll('#f-booklet input:checked')].map(x=>x.value);state.filters.category=$('f-category').value;state.filters.learning=$('f-learning').value;state.filters.mode=$('f-mode').value;state.filters.sort=$('f-sort').value;state.pageSize=Number($('f-page-size').value);state.page=1;replaceNav();renderList()}
[...reviewFields.map(x=>x[1]),'f-exclude-overcome','f-overcome-count','f-flags','f-keyword','f-term','f-session','f-type','f-half','f-booklet','f-category','f-learning','f-mode','f-sort','f-page-size'].forEach(id=>$(id).addEventListener(id==='f-keyword'?'input':'change',readFilters));
function bindFilterValues(){const f=state.filters;for(const [key,id] of reviewFields)$(id).value=f[key]??'';$('f-exclude-overcome').checked=!!f.excludeOvercome;$('f-overcome-count').value=f.overcomeCount||3;$('f-flags').innerHTML=flagChecks(null,f.flags||[]);$('f-keyword').value=f.keyword||'';document.querySelectorAll('#f-term input').forEach(x=>x.checked=selections(f.term).includes(x.value));document.querySelectorAll('#f-session input').forEach(x=>x.checked=selections(f.session).includes(x.value));document.querySelectorAll('#f-type input').forEach(x=>x.checked=selections(f.examType).includes(x.value));document.querySelectorAll('#f-half input').forEach(x=>x.checked=selections(f.examHalf).includes(x.value));document.querySelectorAll('#f-booklet input').forEach(x=>x.checked=selections(f.booklet).includes(x.value));$('f-category').value=f.category||'';$('f-learning').value=f.learning||'';$('f-mode').value=f.mode||'explore';$('f-sort').value=f.sort||'number';$('f-page-size').value=String(state.pageSize||10)}

function scopeQuestions(){if(state.scope==='related'&&state.originId){const q=state.questions.find(x=>x.id===state.originId);const ids=new Set(ExamModel.relatedUnique(q).map(r=>r.question_id));return state.questions.filter(x=>ids.has(x.id))}if(state.scope==='same'&&state.originId){const q=state.questions.find(x=>x.id===state.originId);if(!q?.sameQuestionGroup)return [];return state.questions.filter(x=>x.sameQuestionGroup===q.sameQuestionGroup&&x.id!==q.id)}return state.questions}
function filtered(){return ExamModel.sortQuestions(ExamModel.filter(scopeQuestions(),state.filters,ExamStorage),state.filters.sort,ExamStorage)}
function classificationHtml(q){if(state.filters.mode==='exam')return '<span class="muted">試験形式：分類は非表示</span>';const deps=q.departments.map(d=>`<span class="badge ${d.confirmation_status==='provisional'?'provisional':''}">${esc(d.name)}</span>`).join('');let dis='';if(q.diseaseClassificationStatus==='not_applicable')dis='<span class="badge">疾患対象外</span>';else if(q.diseaseClassificationStatus==='unclassified')dis='<span class="badge">疾患未分類</span>';else dis=q.diseases.map(d=>`<span class="badge provisional">${esc(d.name)}</span>`).join('');return `<div class="badges">${deps}${dis}</div>`}
function relationCell(q){const rel=ExamModel.relatedUnique(q);const ss=ExamModel.sameStatus(q);const same=ss.known?(ss.count===0?'同一問題 0件':`同一問題 ${ss.count??''}`):'同一問題 未調査';return `<div><button class="relation-link same-link" data-id="${esc(q.id)}" ${ss.known&&ss.count===0?'disabled':''}>${same}</button></div><div>${rel.length?`<button class="relation-link rel-link" data-id="${esc(q.id)}">関連問題 ${rel.length}件</button>`:'関連問題 0件'}</div>${q.serialGroupId?'<span class="badge">連問</span>':''}`}
function renderList(){$('exam-results').hidden=true;state.view='list';$('list-view').hidden=false;$('exercise-view').hidden=true;$('nav-back').hidden=!history.state?.parent_entry_id;$('go-home').hidden=state.scope==='all';$('list-title').textContent=state.scope==='related'?'関連問題一覧':state.scope==='same'?'同一問題一覧':'問題一覧';$('list-scope').textContent=state.scope==='all'?`${state.data.questions.length}問（登録済み冊子）`:`${state.originId} を起点・全試験`;const origin=state.originId&&state.questions.find(q=>q.id===state.originId);$('origin-card').hidden=!origin;$('origin-card').innerHTML=origin?`<strong>起点:</strong> ${esc(origin.displayLabel)}<br>${esc(origin.prompt)}`:'';
 renderFacets();const xs=filtered();const total=xs.length,pages=Math.max(1,Math.ceil(total/state.pageSize));if(state.page>pages)state.page=pages;const from=(state.page-1)*state.pageSize, page=xs.slice(from,from+state.pageSize);$('result-count').textContent=`${total}件`;$('start-search-sequence').disabled=total===0;$('page-info').textContent=`${state.page} / ${pages}`;$('prev-page').disabled=state.page<=1;$('next-page').disabled=state.page>=pages;
 $('question-list').innerHTML=page.length?page.map(q=>{const s=ExamStorage.summary(q.id);const cat=q.category==='general'?'一般問題':q.category==='clinical'?'臨床問題':'未判定';return `<div class="qrow" data-id="${esc(q.id)}"><div><div class="qpos">${esc(q.displayLabel)}</div><div class="muted">${esc(q.examDate||'実施日未登録')}</div><span class="badge ${q.categoryStatus==='provisional'?'provisional':''}">${cat}</span></div><div class="qtext">${esc(ExamRichText.plain(q.stem||q.prompt).slice(0,120))}</div><div>${classificationHtml(q)}</div><div>${relationCell(q)}<div class="muted">${s.attempted}回 / 正${s.correct} 誤${s.incorrect} 保留${s.hold} / 連続正解${s.consecutiveCorrect}回<br>${s.last?new Date(s.last).toLocaleString():'未回答'}</div>${flagBadges(q.id)}</div><div class="actions"><button class="solve" data-id="${esc(q.id)}">解く</button><button class="secondary detail" data-id="${esc(q.id)}">解説を見る</button></div></div>`}).join(''):'<p>条件に一致する問題はありません。</p>';
 bindRows();bindFilterValues();renderActiveFilters();if(examRun&&!examRun.finished)document.querySelectorAll('.edit-question').forEach(b=>b.disabled=true);}
function renderFacets(){const depCounts=ExamModel.departmentCounts(scopeQuestions(),state.filters,ExamStorage,state.data.departmentMaster);const q=$('department-search').value.toLowerCase();$('department-options').innerHTML=depCounts.filter(d=>d.name.toLowerCase().includes(q)||d.department_id.includes(q)).map(d=>`<label><input type="checkbox" value="${d.department_id}" ${state.filters.departments.includes(d.department_id)?'checked':''}>${d.department_id}. ${esc(d.name)} <span class="muted">${d.count}件</span></label>`).join('');$('department-summary').textContent=state.filters.departments.length?`${state.filters.departments.length}件選択`:'未選択';$('department-unclassified').checked=state.filters.departmentUnclassified;
 const df=ExamModel.diseaseFacet(scopeQuestions(),state.filters,ExamStorage);$('disease-scope').textContent=`現在の検索結果 ${df.results.length}件から候補`;const s=$('disease-search').value.toLowerCase();$('disease-options').innerHTML=df.candidates.filter(d=>d.name.toLowerCase().includes(s)).map(d=>`<label><input type="checkbox" value="${d.disease_id}" ${state.filters.diseases.includes(d.disease_id)?'checked':''}>${esc(d.name)} <span class="muted">${d.count}件</span></label>`).join('')||'<div class="muted">候補なし</div>';$('disease-unclassified').checked=state.filters.diseaseUnclassified;
 const candIds=new Set(df.candidates.map(d=>d.disease_id));$('selected-disease-tags').innerHTML=state.filters.diseases.map(id=>{const d=state.data.diseaseMaster.find(x=>x.disease_id===id);return `<span class="chip">${esc(d?.name||id)}${candIds.has(id)?'':'（該当0件）'} <button class="linklike remove-disease" data-id="${id}">×</button></span>`}).join('');document.querySelectorAll('.remove-disease').forEach(b=>b.onclick=()=>{state.filters.diseases=state.filters.diseases.filter(x=>x!==b.dataset.id);replaceNav();renderList()});}
function renderActiveFilters(){const c=[];for(const [key,label] of [['wrong','誤答'],['correct','正答'],['streak','連続正解']]){const min=state.filters[key+'Min'],max=state.filters[key+'Max'];if(min!==''&&min!=null)c.push(`${label}${min}回以上`);if(max!==''&&max!=null)c.push(`${label}${max}回以下`)}if(state.filters.excludeOvercome)c.push(`連続正解${state.filters.overcomeCount||3}回以上を除外`);for(const id of state.filters.flags||[])c.push(ExamStorage.flags()[id]);for(const [key,label] of [['term','期'],['session','試験'],['examType','本試/再試'],['examHalf','前半/後半'],['booklet','冊子']]){const chosen=selections(state.filters[key]);if(chosen.length)c.push(label+': '+chosen.join('・'));}if(state.filters.category)c.push(`問題区分:${state.filters.category}`);state.filters.departments.forEach(x=>c.push(`診療科:${x}`));state.filters.diseases.forEach(x=>c.push(`疾患:${state.data.diseaseMaster.find(d=>d.disease_id===x)?.name||x}`));if(state.filters.diseaseUnclassified)c.push('疾患未分類');$('active-filters').innerHTML=c.map(x=>`<span class="chip">${esc(x)}</span>`).join('')}
$('rename-flags').onclick=()=>{const names=ExamStorage.flags();$('flag-name-inputs').innerHTML=ExamStorage.flagIds.map((id,i)=>`<label>フラグ${i+1}<input id="flag-name-${id}" value="${esc(names[id])}" maxlength="30" required></label>`).join('');$('flag-name-error').textContent='';$('flag-name-dialog').showModal()};
