function bindRows(){document.querySelectorAll('.edit-question').forEach(b=>b.onclick=()=>openEditor(b.dataset.id));document.querySelectorAll('.solve').forEach(b=>b.onclick=()=>startSearchSequence(b.dataset.id));document.querySelectorAll('.detail').forEach(b=>b.onclick=()=>openQuestion(b.dataset.id,true,true));document.querySelectorAll('.rel-link').forEach(b=>b.onclick=()=>openScope('related',b.dataset.id));document.querySelectorAll('.same-link:not([disabled])').forEach(b=>b.onclick=()=>openScope('same',b.dataset.id))}
function openScope(scope,id){const parent=snapshot();history.replaceState(parent,'',location.href);state.scope=scope;state.originId=id;state.page=1;state.searchSession=null;state.relationTrail=[];state.filters={keyword:'',term:[],session:[],examType:[],examHalf:[],booklet:[],category:'',departments:[],departmentUnclassified:false,diseases:[],diseaseUnclassified:false,learning:'',mode:'explore',sort:'number'};pushNav();renderList()}
async function sha256(buf){const h=await crypto.subtle.digest('SHA-256',buf);return [...new Uint8Array(h)].map(b=>b.toString(16).padStart(2,'0')).join('')}
async function showAsset(a,token,explanation=false){const box=explanation?$('explanation-images'):$('figure-box'),status=explanation?document.createElement('span'):$('figure-status');status.textContent='画像を読み込み中';try{const storedBlob=await WebStore.asset(a);const buf=await storedBlob.arrayBuffer();const hash=await sha256(buf);if(token!==renderToken)return;if(hash!==a.sha256)throw new Error('SHA256不一致');ExamStorage.setAsset(a.asset_id,{state:'verified',hash,verifiedAt:new Date().toISOString()});const blob=new Blob([buf],{type:a.mime_type});const img=new Image();img.alt=a.alt||'設問画像';img.tabIndex=0;img.setAttribute('role','button');img.setAttribute('aria-label',`${img.alt}を拡大表示`);img.onclick=()=>openImageViewer(img);img.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openImageViewer(img)}};img.onload=()=>{if(token!==renderToken)return;displayedAssets[a.asset_id]={state:"displayed"};ExamStorage.setAsset(a.asset_id,{state:'displayed',displayedAt:new Date().toISOString()});status.textContent='画像を表示・クリックで拡大可能';updateSubmitReady();};img.onerror=()=>{if(token!==renderToken)return;displayedAssets[a.asset_id]={state:"failed"};ExamStorage.setAsset(a.asset_id,{state:'failed',reason:'decode/display error'});status.textContent='提示図あり・表示できません（再試行）';updateSubmitReady()};img.src=URL.createObjectURL(blob);box.appendChild(img);box.hidden=false}catch(e){if(token!==renderToken)return;displayedAssets[a.asset_id]={state:"failed"};ExamStorage.setAsset(a.asset_id,{state:'failed',reason:String(e)});status.textContent='提示図あり・表示できません（再試行）';if(explanation){const note=document.createElement('p');note.textContent='解説画像を表示できません。パッケージ内の画像を確認してください。';box.append(note);box.hidden=false}else if(!box.querySelector('img'))box.hidden=true;updateSubmitReady()}}
function renderExplanationImages(q){const box=$('explanation-images');box.querySelectorAll('img').forEach(i=>URL.revokeObjectURL(i.src));box.innerHTML='';for(const a of (q.assets||[]).filter(a=>a.role==='explanation_image'))showAsset(a,renderToken,true)}
function updateSubmitReady(){const q=current();if(!q)return;const ready=ExamModel.attemptReady(q,displayedAssets);$('submit').disabled=!ready.ready||state.studyView||!!state.lastAttemptId;$('skip').hidden=false;if(ready.state==='disabled')$('selection-hint').textContent='この問題は解答不可に設定されています。';else if(!ready.ready&&ExamModel.visibleAssets(q).some(a=>a.required_for_attempt!==false))$('selection-hint').textContent='必要な提示図が表示確認されるまで通常演習の採点は開始できません。';else $('selection-hint').textContent=q.selectionCountInferred?'該当するものをすべて選択':q.requiredCount>1?`${q.requiredCount}つ選択`:'1つ選択';}
function current(){return (examRun&&state.view==='exercise'&&(examReviewIndex!==null||!examRun.finished)?examRun.questions.find(q=>q.id===state.currentId):null)||state.questions.find(q=>q.id===state.currentId)}
